"""Inspect only declared mute/drums windows; preserve both timing-limited predecessors."""
import datetime,hashlib,json,subprocess
from pathlib import Path
import numpy as np
R=Path(__file__).resolve().parents[1];out=R/'docs/prototype/desktop-0.1.9-r3-stem-inspection.json';D=R/'local-evidence/desktop-0.1.9-stem-audio';assert not out.exists() and not D.exists();D.mkdir();plan=json.loads((R/'docs/prototype/desktop-0.1.9-r3-stem-plan.json').read_text());records=[];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
for name,scope in [('open-play-native-019-stems-attempt1-ended.webm','Track ended before drums action; timing-limited predecessor'),('open-play-native-019-stems-attempt2-ended.webm','Midpoint seek/Home did not reset to zero; source ended before drums action; EOF state bug separately observed'),('open-play-native-019-stems-attempt3-bounded.webm','Cue reset to zero, single timed native control sequence')]:
 source=Path('/Users/jasonpoindexter/Downloads')/name;copy=D/name;copy.write_bytes(source.read_bytes());probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_streams','-show_format','-of','json',str(source)]));stream=[s for s in probe['streams'] if s['codec_type']=='audio'];assert len(stream)==1;sr=int(stream[0]['sample_rate']);ch=int(stream[0]['channels']);assert ch==2;raw=D/(name+'.whole-f32le');subprocess.run(['ffmpeg','-v','error','-nostdin','-n','-i',str(source),'-map','0:a:0','-c:a','pcm_f32le','-f','f32le',str(raw)],check=True);y=np.fromfile(raw,dtype='<f4').reshape(-1,ch);finite=bool(np.isfinite(y).all());quiet=y[sr:2*sr].astype(float);drums=y[-2*sr:].astype(float);assert len(quiet)==sr and len(drums)==2*sr;peak=float(np.max(np.abs(quiet)));levels=np.sqrt(np.mean(drums*drums,axis=0)).tolist();passed=finite and peak==0 and min(levels)>.001;records.append({'name':name,'scope':scope,'originalSHA256':sha(source),'bytes':source.stat().st_size,'copyMatchesOriginal':sha(source)==sha(copy),'wholeDecode':{'path':str(raw.relative_to(R)),'sha256':sha(raw),'frames':len(y),'sampleRate':sr,'channels':ch,'seconds':len(y)/sr,'finite':finite},'quietWindowSeconds':[1,2],'quietPeak':peak,'drumsWindow':'final2seconds','drumsRMS':levels,'declaredCriteriaPassed':passed})
report={'checkedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'plan':plan,'records':records,'boundedAttemptPassed':records[-1]['declaredCriteriaPassed'],'scope':'One real native five-source mute→drums path. Whole originals retained. No separated-component identity/quality, transient/pitch/cursor/latency/hardware/vendor/fullparity acceptance.','fullParityVerified':False};out.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'records':[{'name':r['name'],'seconds':r['wholeDecode']['seconds'],'quietPeak':r['quietPeak'],'drumsRMS':r['drumsRMS'],'passed':r['declaredCriteriaPassed']} for r in records]},indent=2))
